-- Generated installation schema and source-pinned data; runtime reads the database only.
CREATE TABLE IF NOT EXISTS `#__joomengine_mcp_provider` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `asset_id` INT NOT NULL DEFAULT 0,
  `name` VARCHAR(190) NOT NULL DEFAULT '',
  `title` VARCHAR(190) NOT NULL DEFAULT '',
  `published` INT NOT NULL DEFAULT 1,
  `access` INT NOT NULL DEFAULT 1,
  `ordering` INT NOT NULL DEFAULT 0,
  `checked_out` INT NULL DEFAULT NULL,
  `checked_out_time` DATETIME NULL DEFAULT NULL,
  `created` DATETIME NULL DEFAULT NULL,
  `created_by` INT NOT NULL DEFAULT 0,
  `modified` DATETIME NULL DEFAULT NULL,
  `modified_by` INT NOT NULL DEFAULT 0,
  `version` INT NOT NULL DEFAULT 1,
  `params` MEDIUMTEXT NOT NULL,
  `seed_revision` VARCHAR(64) NOT NULL DEFAULT '',
  `seed_hash` VARCHAR(64) NOT NULL DEFAULT '',
  `customized` INT NOT NULL DEFAULT 0,
  `extension` VARCHAR(190) NOT NULL DEFAULT '',
  `description` MEDIUMTEXT NOT NULL,
  `definition` MEDIUMTEXT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE INDEX `#__jemcp_provider_published` ON `#__joomengine_mcp_provider` (`published`);

CREATE TABLE IF NOT EXISTS `#__joomengine_mcp_schema` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `asset_id` INT NOT NULL DEFAULT 0,
  `name` VARCHAR(190) NOT NULL DEFAULT '',
  `title` VARCHAR(190) NOT NULL DEFAULT '',
  `published` INT NOT NULL DEFAULT 1,
  `access` INT NOT NULL DEFAULT 1,
  `ordering` INT NOT NULL DEFAULT 0,
  `checked_out` INT NULL DEFAULT NULL,
  `checked_out_time` DATETIME NULL DEFAULT NULL,
  `created` DATETIME NULL DEFAULT NULL,
  `created_by` INT NOT NULL DEFAULT 0,
  `modified` DATETIME NULL DEFAULT NULL,
  `modified_by` INT NOT NULL DEFAULT 0,
  `version` INT NOT NULL DEFAULT 1,
  `params` MEDIUMTEXT NOT NULL,
  `seed_revision` VARCHAR(64) NOT NULL DEFAULT '',
  `seed_hash` VARCHAR(64) NOT NULL DEFAULT '',
  `customized` INT NOT NULL DEFAULT 0,
  `provider_id` INT NOT NULL,
  `document` MEDIUMTEXT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE (`name`),
  FOREIGN KEY (`provider_id`) REFERENCES `#__joomengine_mcp_provider` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE INDEX `#__jemcp_schema_provider_id` ON `#__joomengine_mcp_schema` (`provider_id`);
CREATE INDEX `#__jemcp_schema_published` ON `#__joomengine_mcp_schema` (`published`);

