INSERT INTO `#__joomengine_mcp_tool` (`id`, `provider_id`, `name`, `title`, `description`, `handler`, `input_schema_id`, `output_schema_id`, `configuration`, `definition`, `asset_id`, `published`, `access`, `ordering`, `checked_out`, `checked_out_time`, `created`, `created_by`, `modified`, `modified_by`, `version`, `params`, `seed_revision`, `seed_hash`, `customized`) VALUES (5, 1, 'joomla_action_read', 'Run an enabled Joomla read action', 'Executes one catalogue action by semantic identifier. Routes, origins, credentials, methods, and toolsets remain server controlled. Some source-defined GET operations perform Joomla bookkeeping; inspect the action descriptor before execution.', 'action.read', 393, NULL, '{}', '{"name":"joomla_action_read","title":"Run an enabled Joomla read action","description":"Executes one catalogue action by semantic identifier. Routes, origins, credentials, methods, and toolsets remain server controlled. Some source-defined GET operations perform Joomla bookkeeping; inspect the action descriptor before execution.","annotations":{"readOnlyHint":false,"destructiveHint":false,"idempotentHint":true,"openWorldHint":false},"execution":{"taskSupport":"forbidden"}}', 0, 1, 1, 0, NULL, NULL, '2026-09-17 00:00:00', 0, NULL, 0, 1, '{}', '2cff50f4f6b440da3c684f9995a77efad32e1a36', 'c97872a08182eab21bf1f291ad0137069a8c3475b9fc1df4b16c49da292b3467', 0);
INSERT INTO `#__joomengine_mcp_tool` (`id`, `provider_id`, `name`, `title`, `description`, `handler`, `input_schema_id`, `output_schema_id`, `configuration`, `definition`, `asset_id`, `published`, `access`, `ordering`, `checked_out`, `checked_out_time`, `created`, `created_by`, `modified`, `modified_by`, `version`, `params`, `seed_revision`, `seed_hash`, `customized`) VALUES (6, 1, 'joomla_permission_request', 'Request permission for Joomla writes', 'Creates a principal-bound operator permission request for selected configured write or administration toolsets. Returns an exact acknowledgement phrase that must be shown to and supplied by the operator. It does not grant permission.', 'permission.request', 394, NULL, '{}', '{"name":"joomla_permission_request","title":"Request permission for Joomla writes","description":"Creates a principal-bound operator permission request for selected configured write or administration toolsets. Returns an exact acknowledgement phrase that must be shown to and supplied by the operator. It does not grant permission.","annotations":{"readOnlyHint":false,"destructiveHint":false,"idempotentHint":false,"openWorldHint":false},"execution":{"taskSupport":"forbidden"}}', 0, 1, 1, 0, NULL, NULL, '2026-09-17 00:00:00', 0, NULL, 0, 1, '{}', '2cff50f4f6b440da3c684f9995a77efad32e1a36', '48792407486e7c2442049dd1c564e9b6659b30bd89fd257c87ad7b403a01569d', 0);
INSERT INTO `#__joomengine_mcp_tool` (`id`, `provider_id`, `name`, `title`, `description`, `handler`, `input_schema_id`, `output_schema_id`, `configuration`, `definition`, `asset_id`, `published`, `access`, `ordering`, `checked_out`, `checked_out_time`, `created`, `created_by`, `modified`, `modified_by`, `version`, `params`, `seed_revision`, `seed_hash`, `customized`) VALUES (7, 1, 'joomla_permission_approve', 'Approve a requested Joomla permission', 'Validates the exact operator-supplied acknowledgement for a pending request and creates a principal-bound grant. The grant cannot exceed configured site toolsets, inbound OAuth scopes, or Joomla ACL.', 'permission.approve', 395, NULL, '{}', '{"name":"joomla_permission_approve","title":"Approve a requested Joomla permission","description":"Validates the exact operator-supplied acknowledgement for a pending request and creates a principal-bound grant. The grant cannot exceed configured site toolsets, inbound OAuth scopes, or Joomla ACL.","annotations":{"readOnlyHint":false,"destructiveHint":true,"idempotentHint":false,"openWorldHint":false},"execution":{"taskSupport":"forbidden"}}', 0, 1, 1, 0, NULL, NULL, '2026-09-17 00:00:00', 0, NULL, 0, 1, '{}', '2cff50f4f6b440da3c684f9995a77efad32e1a36', '786d37b1b8fa3029c9238991684eac92b27fcf85cf92b8b563a40fe207198c9a', 0);
INSERT INTO `#__joomengine_mcp_tool` (`id`, `provider_id`, `name`, `title`, `description`, `handler`, `input_schema_id`, `output_schema_id`, `configuration`, `definition`, `asset_id`, `published`, `access`, `ordering`, `checked_out`, `checked_out_time`, `created`, `created_by`, `modified`, `modified_by`, `version`, `params`, `seed_revision`, `seed_hash`, `customized`) VALUES (8, 1, 'joomla_permissions_list', 'List active Joomla permissions', 'Lists only the authenticated principal’s active grants, their site, toolsets, duration, expiry, and remaining use count. No acknowledgement phrase or principal identity is returned.', 'permission.list', 389, NULL, '{}', '{"name":"joomla_permissions_list","title":"List active Joomla permissions","description":"Lists only the authenticated principal’s active grants, their site, toolsets, duration, expiry, and remaining use count. No acknowledgement phrase or principal identity is returned.","annotations":{"readOnlyHint":true,"destructiveHint":false,"idempotentHint":true,"openWorldHint":false},"execution":{"taskSupport":"forbidden"}}', 0, 1, 1, 0, NULL, NULL, '2026-09-17 00:00:00', 0, NULL, 0, 1, '{}', '2cff50f4f6b440da3c684f9995a77efad32e1a36', 'daf5cfa6301c6cebdc81d96a66333c4219a91d186fd62ff6dccce2b75fe0c7ff', 0);
